css:
button, button:focus {
  font-size: 20px;
  padding: 12px 30px;
  border-radius: 5px;
  background-color: #ff9800;
  border: 2px solid #f57c00;
  color: #fff;
  box-shadow: 0px 2px 4px rgba(0, 0, 0, 0.3);
  transition: 0.3s;
  cursor: pointer;
}

button:hover {
  background-color: #f57c00;
}

button:active {
  transform: translateY(2px);
  box-shadow: 0px 0px 0px rgba(0, 0, 0, 0.3);
}
